create or replace function private.weekly_source_pay_decision_unprotect_apply_v1(
 p_preparation_id uuid,p_decision_id uuid,p_member_key text,p_request_id uuid
) returns jsonb language plpgsql volatile security definer set search_path=pg_catalog,private,public

retainedNonFunctionEffects.statement:
alter table private.weekly_source_pay_decisions add constraint source_pay_decision_accept_request_fk
 foreign key(id,accept_request_id) references private.weekly_source_pay_decision_requests(decision_id,request_id)
 deferrable initially deferred;

alter table private.weekly_source_pay_decision_preview_assemblies add constraint source_pay_assembly_review_triangle_fk
 foreign key(decision_id,id,review_id) references private.weekly_source_pay_decision_reviews(decision_id,preview_assembly_id,id)
 deferrable initially deferred;

alter table private.weekly_source_pay_decision_requests add constraint source_pay_request_review_fk
 foreign key(decision_id,review_id) references private.weekly_source_pay_decision_reviews(decision_id,id)
 deferrable initially deferred;

do $source_pay_private_rls$
declare name text;
begin
 foreach name in array array['weekly_source_pay_decisions','weekly_source_pay_decision_requests',
  'weekly_source_pay_decision_preview_assemblies','weekly_source_pay_decision_preview_quotes','weekly_source_pay_decision_reviews',
  'weekly_source_pay_decision_members','weekly_source_pay_decision_bindings','weekly_source_pay_decision_unprotect_preparations',
  'weekly_source_pay_decision_acceptance_applications','weekly_source_pay_decision_native_adoptions','weekly_source_pay_decision_publication_adoptions'] loop
  execute format('alter table private.%I enable row level security',name);
  execute format('alter table private.%I force row level security',name);
  execute format('revoke all on table private.%I from public,anon,authenticated,service_role',name);
  execute format('create policy cloudtms_source_pay_decision_owner_only on private.%I for all to %I using(true) with check(true)',name,current_user);
 end loop;
end;
$source_pay_private_rls$;

alter table public.weekly_discrepancy_incidents add constraint weekly_discrepancy_incidents_resolution_kind_check
 check(resolution_kind is null or resolution_kind in('SOURCE_MATCHED','OFFICE_ACCEPTED_SYSTEM_HOURS','CANDIDATE_CORRECTED',
  'MANAGER_CONFIRMED_SYSTEM_HOURS','RECORDED_NOT_WORKED','CORRECT_FINAL_SOURCE','SOURCE_PAY_DECISION'));

